 @EventHandler public void onJoin(PlayerJoinEvent e){Player p=e.getPlayer();var blacklist=db.rows("SELECT reason FROM blacklists WHERE uuid=? AND active=1",id(p));if(!blacklist.isEmpty()){p.kickPlayer("§cYou are blacklisted: "+blacklist.getFirst().get("reason"));return;}try{db.update("INSERT INTO player_data(uuid,last_name,first_join,last_seen) VALUES(?,?,?,?) ON CONFLICT(uuid) DO UPDATE SET last_name=excluded.last_name,last_seen=excluded.last_seen",id(p),p.getName(),System.currentTimeMillis(),System.currentTimeMillis());db.update("INSERT OR IGNORE INTO player_stats(uuid) VALUES(?)",id(p));}catch(Exception ignored){}boolean hidden=Boolean.parseBoolean(db.preference(p.getUniqueId(),"hide-players","false"));for(Player other:Bukkit.getOnlinePlayers())if(other!=p){if(hidden)p.hidePlayer(plugin,other);if(Boolean.parseBoolean(db.preference(other.getUniqueId(),"vanished","false"))&&!staff(p))p.hidePlayer(plugin,other);}if(Boolean.parseBoolean(db.preference(p.getUniqueId(),"staffmode","false"))){p.setAllowFlight(true);p.setFlying(true);db.setPreference(p.getUniqueId(),"vanished","true");}if(Boolean.parseBoolean(db.preference(p.getUniqueId(),"vanished","false")))for(Player t:Bukkit.getOnlinePlayers())if(t!=p&&!staff(t))t.hidePlayer(plugin,p);plugin.getScoreboard().update(p);}
 @EventHandler public void onQuit(PlayerQuitEvent e){UUID id=e.getPlayer().getUniqueId();requests.remove(id);replies.remove(id);pendingTeleports.remove(id);}
 @EventHandler public void onPhantomSpawn(org.bukkit.event.entity.EntitySpawnEvent e){if(!(e.getEntity() instanceof org.bukkit.entity.Phantom))return;int radius=plugin.getConfig().getInt("phantom.radius",64);boolean nearby=false,allowed=false;for(Player p:e.getLocation().getWorld().getPlayers())if(p.getLocation().distanceSquared(e.getLocation())<=radius*radius){nearby=true;if(Boolean.parseBoolean(db.preference(p.getUniqueId(),"phantom-enabled","true")))allowed=true;}if(nearby&&!allowed)e.setCancelled(true);}
